const amtlich = (id, wert, einheit, quelle, notiz, extra = {}) => ({
  id,
  wert,
  einheit,
  land: "DE",
  quelle,
  abruf: ABRUF,
  gueltigAb: null,
  gueltigBis: null,
  status: "geprueft",
  pruefer: B5,
  klasse: "A",
  notiz,
  ...extra,
