const JAHR_2026 = { gueltigAb: "2026-01-01", gueltigBis: "2026-12-31" };

/* ------------------------------------------------------------------ */
/* Umlagen 2026 (bundesweit einheitlich)                               */
/* ------------------------------------------------------------------ */

