  amtlich("umlage.offshoreNetz", 0.941, "ct/kWh", Q.offshore, "Offshore-Netzumlage 2026 (§ 17f EnWG i. V. m. EnFG), Seite „Offshore-Netzumlage 2026“: 0,941 ct/kWh.", JAHR_2026),
  amtlich(
