  amtlich("umlage.besondereNetznutzung.grenzeKwh", 1000000, "kWh", Q.aufschlag, "Grenze der Letztverbrauchergruppen A‘/B‘/C‘ je Abnahmestelle und Jahr.", JAHR_2026),
