  nah(r.rechnung.eur, 100000 * 0.12 + r.amtlich.eur + 100000 * 0.06 + 1200, 0.01);
  // ohne Netz: Urteil trotzdem möglich (Energie steht getrennt), Rechnungssumme unbekannt
